#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K;
    cin >> N >> K;

    vector<vector<int>> graph(N);
    for (int i = 0; i < N - 1; ++i) {
        int a, b;
        cin >> a >> b;
        --a;
        --b;
        graph[a].push_back(b);
        graph[b].push_back(a);
    }

    if (N == 1) {
        cout << 0 << '\n';
        return 0;
    }

    int LOG = 1;
    while ((1 << LOG) <= N) ++LOG;

    vector<int> parent(N), depth(N), order;
    order.reserve(N);
    parent[0] = 0;
    order.push_back(0);

    for (int i = 0; i < (int)order.size(); ++i) {
        int u = order[i];
        for (int v : graph[u]) {
            if (v == parent[u] && u != 0) continue;
            if (v == 0 && u == 0) continue;
            parent[v] = u;
            depth[v] = depth[u] + 1;
            order.push_back(v);
        }
    }

    vector<vector<int>> up(LOG, vector<int>(N));
    up[0] = parent;
    for (int j = 1; j < LOG; ++j) {
        for (int v = 0; v < N; ++v) {
            up[j][v] = up[j - 1][up[j - 1][v]];
        }
    }

    vector<int> sortedVertices(N);
    iota(sortedVertices.begin(), sortedVertices.end(), 0);
    sort(sortedVertices.begin(), sortedVertices.end(),
         [&](int a, int b) { return depth[a] > depth[b]; });

    vector<vector<pair<int, int>>> centroidPaths(N);
    vector<char> removed(N, false);
    vector<int> tempParent(N), subtreeSize(N);

    function<void(int)> buildCentroid = [&](int entry) {
        vector<int> nodes;
        nodes.push_back(entry);
        tempParent[entry] = -1;

        for (int i = 0; i < (int)nodes.size(); ++i) {
            int u = nodes[i];
            for (int v : graph[u]) {
                if (removed[v] || v == tempParent[u]) continue;
                tempParent[v] = u;
                nodes.push_back(v);
            }
        }

        for (int u : nodes) subtreeSize[u] = 1;
        for (int i = (int)nodes.size() - 1; i > 0; --i) {
            int u = nodes[i];
            subtreeSize[tempParent[u]] += subtreeSize[u];
        }

        int total = (int)nodes.size();
        int centroid = entry;
        for (int u : nodes) {
            int largestPart = total - subtreeSize[u];
            for (int v : graph[u]) {
                if (!removed[v] && tempParent[v] == u) {
                    largestPart = max(largestPart, subtreeSize[v]);
                }
            }
            if (largestPart * 2 <= total) {
                centroid = u;
                break;
            }
        }

        removed[centroid] = true;

        vector<tuple<int, int, int>> stack;
        stack.emplace_back(centroid, -1, 0);
        while (!stack.empty()) {
            auto [u, p, dist] = stack.back();
            stack.pop_back();
            centroidPaths[u].emplace_back(centroid, dist);

            for (int v : graph[u]) {
                if (v == p || removed[v]) continue;
                stack.emplace_back(v, u, dist + 1);
            }
        }

        for (int v : graph[centroid]) {
            if (!removed[v]) buildCentroid(v);
        }
    };

    buildCentroid(0);

    const int INF = 1e9;
    vector<int> best(N, INF);

    auto feasible = [&](int radius) {
        fill(best.begin(), best.end(), INF);
        int centers = 0;

        for (int v : sortedVertices) {
            int nearest = INF;
            for (auto [c, d] : centroidPaths[v]) {
                nearest = min(nearest, best[c] + d);
            }

            if (nearest <= radius) continue;

            ++centers;
            if (centers > K) return false;

            int c = v;
            int steps = radius;
            for (int bit = 0; bit < LOG; ++bit) {
                if (steps & (1 << bit)) c = up[bit][c];
            }

            for (auto [centroid, d] : centroidPaths[c]) {
                best[centroid] = min(best[centroid], d);
            }
        }

        return true;
    };

    int low = 0, high = N - 1;
    while (low < high) {
        int mid = low + (high - low) / 2;
        if (feasible(mid)) high = mid;
        else low = mid + 1;
    }

    cout << low << '\n';
    return 0;
}
